query m_reset() {
  delete Entry where true
  delete Task where true
  delete Agent where true
  delete Skill where true
}

query m_o1_fixture($task_id: String, $skill_id: String) {
  insert Skill { id: $skill_id }
  insert Task { id: $task_id, state: "open" }
  insert Needs { from: $task_id, to: $skill_id }
}

query m_fixture_base($task_id: String, $skill_id: String) {
  insert Skill { id: $skill_id }
  insert Task { id: $task_id, state: "open" }
  insert Needs { from: $task_id, to: $skill_id }
  insert Entry {
    id: "entry-0",
    seq: 0,
    rule: "genesis",
    hash: "0",
    prev: "",
    ts: 0
  }
}

query q_task($task_id: String) {
  match {
